package com.transportlogistics.app.tracking.adapters.inbound.web.controllers;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.transportlogistics.app.shared.domain.BusinessRuleException;
import com.transportlogistics.app.shared.web.ApiError;
import com.transportlogistics.app.shared.web.CorrelationIdFilter;
import com.transportlogistics.app.tracking.domain.TrackingModels.EngineState;
import com.transportlogistics.app.tracking.ports.inbound.TrackingUseCase.PositionCommand;
import com.transportlogistics.app.tracking.ports.outbound.TrackingStore;
import com.transportlogistics.app.tracking.domain.TrackingModels.ProviderBindingLifecycle;
import com.transportlogistics.app.integration.IntegrationSecretResolver;
import com.transportlogistics.app.tracking.adapters.inbound.gateway.TelemetryPayloadNormalizerRegistry;
import com.transportlogistics.app.tracking.application.provider.NormalizedTelemetryPoint;
import com.transportlogistics.app.tracking.application.provider.TelemetryGatewayType;
import com.transportlogistics.app.tracking.application.telemetry.TrackingTelemetryIngestedV1;
import com.transportlogistics.app.tracking.ports.outbound.TelemetryStreamPublisherPort;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.springframework.http.MediaType;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/integration/v1/tracking")
public class TrackingIngestionController {
 private final TrackingStore store;private final ObjectMapper json;private final IntegrationSecretResolver secrets;private final TrackingIngressGuard guard;private final MeterRegistry meters;private final TelemetryPayloadNormalizerRegistry normalizers;private final TelemetryStreamPublisherPort stream;private final Duration acknowledgementTimeout;
 public TrackingIngestionController(TrackingStore store,ObjectMapper json,IntegrationSecretResolver secrets,TrackingIngressGuard guard,MeterRegistry meters,TelemetryPayloadNormalizerRegistry normalizers,TelemetryStreamPublisherPort stream,@org.springframework.beans.factory.annotation.Value("${app.tracking.kafka.acknowledgement-timeout:PT10S}") Duration acknowledgementTimeout){this.store=store;this.json=json;this.secrets=secrets;this.guard=guard;this.meters=meters;this.normalizers=normalizers;this.stream=stream;this.acknowledgementTimeout=acknowledgementTimeout;}
 @PostMapping(value="/positions",consumes=MediaType.APPLICATION_JSON_VALUE)
 public ResponseEntity<List<AcceptedTelemetry>> ingest(@RequestHeader(value="X-Tracking-Provider-Key-Id",required=false)String providerKeyId,@RequestHeader(value="X-Tracking-Provider",required=false)String assertedProvider,@RequestHeader(value="X-Tracking-Timestamp",required=false)String epochValue,@RequestHeader(value="X-Tracking-Nonce",required=false)String nonce,@RequestHeader(value="X-Tracking-Signature",required=false)String signature,@RequestHeader(value="X-Tracking-Payload-Version",defaultValue="1")int payloadVersion,@RequestBody String body,HttpServletRequest request){
  Timer.Sample sample=Timer.start(meters);String metricProvider="UNKNOWN";try{if(body.getBytes(StandardCharsets.UTF_8).length>1_048_576)throw error("TRACKING_POSITION_INVALID","Request exceeds 1 MiB");if(blank(providerKeyId)||blank(assertedProvider)||blank(epochValue)||blank(nonce)||blank(signature))throw unauthorized();long epoch;try{epoch=Long.parseLong(epochValue);}catch(NumberFormatException e){throw unauthorized();}var binding=store.providerBinding(providerKeyId).filter(b->b.lifecycle()==ProviderBindingLifecycle.ACTIVE).orElseThrow(TrackingIngestionController::unauthorized);metricProvider=binding.providerAlias();if(!binding.providerAlias().equalsIgnoreCase(assertedProvider))throw unauthorized();Instant now=Instant.now();Instant signedAt;try{signedAt=Instant.ofEpochSecond(epoch);}catch(DateTimeException e){throw unauthorized();}if(Duration.between(signedAt,now).abs().compareTo(Duration.ofMinutes(5))>0)throw unauthorized();char[] secret=secrets.resolve(binding.credentialReference()).orElseThrow(TrackingIngestionController::unauthorized);try{String canonical=epoch+"\n"+nonce+"\n"+providerKeyId+"\n"+assertedProvider+"\n"+body;if(!MessageDigest.isEqual(hmac(secret,canonical),hex(signature)))throw unauthorized();}finally{Arrays.fill(secret,'\0');}String nonceHash=sha(nonce);if(!store.reserveNonce(binding.tenantId(),binding.id(),nonceHash,now,now.plus(Duration.ofMinutes(10))))throw unauthorized();
  if(payloadVersion!=1)throw error("TRACKING_PAYLOAD_VERSION_UNSUPPORTED","Unsupported telemetry payload version");JsonNode root=json.readTree(body);List<JsonNode> input;if(root.isArray())input=elements(root);else if(root.has("positions")&&root.get("positions").isArray())input=elements(root.get("positions"));else input=List.of(root);if(input.isEmpty()||input.size()>500)throw error("TRACKING_POSITION_INVALID","Batch size must be 1..500");guard.admit(binding.tenantId(),binding.providerAlias(),input.size());TelemetryGatewayType type=store.providerType(binding.tenantId(),binding.id()).orElseGet(()->fixtureType(binding.providerAlias()));var normalizer=normalizers.require(type);String correlation=(String)request.getAttribute(CorrelationIdFilter.ATTRIBUTE);List<AcceptedTelemetry> accepted=new ArrayList<>(input.size());for(JsonNode node:input){NormalizedTelemetryPoint point=normalizer.normalize(json.writeValueAsString(node),binding.tenantId());var authority=store.ingressDeviceAuthority(binding.tenantId(),binding.id(),point.externalDeviceReference(),point.recordedAt()).orElseThrow(TrackingIngestionController::unauthorized);String dedupe=sha(binding.tenantId()+"|"+binding.providerAlias()+"|"+(point.providerMessageId()!=null?point.providerMessageId():authority.deviceId()+"|"+point.recordedAt()+"|"+point.latitude().toPlainString()+"|"+point.longitude().toPlainString()));UUID eventId=UUID.nameUUIDFromBytes(dedupe.getBytes(StandardCharsets.UTF_8));var event=new TrackingTelemetryIngestedV1(eventId,TrackingTelemetryIngestedV1.TYPE,TrackingTelemetryIngestedV1.VERSION,binding.tenantId(),authority.vehicleId(),authority.deviceId(),binding.providerAlias(),point.providerMessageId(),dedupe,point.latitude(),point.longitude(),point.speedKph(),point.headingDegrees(),point.horizontalAccuracyMeters(),null,point.engineState(),point.odometerKm(),null,point.recordedAt(),now);String key=binding.tenantId()+":"+authority.vehicleId();var publication=stream.publishDurably(key,event,correlation,acknowledgementTimeout);accepted.add(new AcceptedTelemetry(eventId,authority.vehicleId(),dedupe,publication.partition(),publication.offset()));}return ResponseEntity.accepted().body(List.copyOf(accepted));}catch(ProviderAuthenticationException e){meters.counter("tracking.ingress.provider_auth_failure","provider",metricProvider.toUpperCase(Locale.ROOT)).increment();throw e;}catch(BusinessRuleException e){String metric=e.code().equals("TRACKING_POSITION_CONFLICT")?"conflict":"invalid";meters.counter("tracking.ingress."+metric,"provider",metricProvider.toUpperCase(Locale.ROOT)).increment();if("TRACKING_PROVIDER_UNAUTHORIZED".equals(e.code()))throw unauthorized();throw e;}catch(JsonProcessingException e){meters.counter("tracking.ingress.invalid","provider",metricProvider.toUpperCase(Locale.ROOT)).increment();throw error("TRACKING_POSITION_INVALID","Malformed telemetry JSON");}finally{sample.stop(meters.timer("tracking.ingress.processing.latency","provider",metricProvider.toUpperCase(Locale.ROOT)));}
 }
 private static List<JsonNode> elements(JsonNode array){List<JsonNode> result=new ArrayList<>();array.elements().forEachRemaining(result::add);return result;}
 private static TelemetryGatewayType fixtureType(String alias){if("FIXTURE".equalsIgnoreCase(alias))return TelemetryGatewayType.GENERIC;throw error("TRACKING_PROVIDER_TYPE_UNSUPPORTED","Telemetry gateway type is unsupported");}
 public record AcceptedTelemetry(UUID eventId,UUID vehicleId,String dedupeIdentity,int partition,long offset){}
 public record PositionRequest(UUID deviceId,String providerMessageId,Long providerSequence,Instant sourceTimestamp,BigDecimal latitude,BigDecimal longitude,BigDecimal horizontalAccuracyMeters,BigDecimal speedKph,BigDecimal headingDegrees,BigDecimal altitudeMeters,EngineState engineState,BigDecimal odometerKm,BigDecimal engineHours,Map<String,String> safeMetadata){PositionCommand command(){return new PositionCommand(deviceId,providerMessageId,providerSequence,sourceTimestamp,latitude,longitude,horizontalAccuracyMeters,speedKph,headingDegrees,altitudeMeters,engineState,odometerKm,engineHours,safeMetadata);}}
 private static byte[] hmac(char[] secret,String value){try{Mac m=Mac.getInstance("HmacSHA256");byte[] key=new String(secret).getBytes(StandardCharsets.UTF_8);try{m.init(new SecretKeySpec(key,"HmacSHA256"));return m.doFinal(value.getBytes(StandardCharsets.UTF_8));}finally{Arrays.fill(key,(byte)0);}}catch(Exception e){throw new IllegalStateException(e);}}
 private static byte[] hex(String s){try{return HexFormat.of().parseHex(s);}catch(Exception e){return new byte[0];}}
 private static String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static boolean blank(String value){return value==null||value.isBlank();}
 @ExceptionHandler(ProviderAuthenticationException.class) ResponseEntity<ApiError> providerAuthentication(ProviderAuthenticationException ignored,HttpServletRequest request){var body=new ApiError(OffsetDateTime.now(),401,"Unauthorized","TRACKING_PROVIDER_UNAUTHORIZED","Provider authentication failed",request.getRequestURI(),(String)request.getAttribute(CorrelationIdFilter.ATTRIBUTE),List.of());return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(body);}
 private static ProviderAuthenticationException unauthorized(){return new ProviderAuthenticationException();}private static BusinessRuleException error(String c,String m){return new BusinessRuleException(c,m);}private static final class ProviderAuthenticationException extends RuntimeException {}
}
